anM(a,b){return"\u091d\u091f\u092a\u091f \u0935\u093e\u0932\u093e \u091c\u0935\u093e\u092c "+a+" \u0939\u094b\u0924\u093e, \u0924\u094b \u0915\u0941\u0932 "+b+" \u0939\u094b \u091c\u093e\u0924\u093e\u0964"},
anN(a,b,c){return"\u0905\u0917\u0930 "+a+" \u092e\u0936\u0940\u0928\u0947\u0902 "+b+" \u092e\u093f\u0928\u091f \u092e\u0947\u0902 "+a+" \u0916\u093f\u0932\u094c\u0928\u0947 \u092c\u0928\u093e\u0924\u0940 \u0939\u0948\u0902, \u0924\u094b "+c+" \u092e\u0936\u0940\u0928\u094b\u0902 \u0915\u094b "+c+" \u0916\u093f\u0932\u094c\u0928\u0947 \u092c\u0928\u093e\u0928\u0947 \u092e\u0947\u0902 \u0915\u093f\u0924\u0928\u0947 \u092e\u093f\u0928\u091f \u0932\u0917\u0947\u0902\u0917\u0947?"},
