anQ(a,b,c,d){return"100 \u0938\u0947 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902: "+a+"% \u092c\u0922\u093c\u0928\u0947 \u092a\u0930 "+b+" \u0939\u0941\u0906, \u0914\u0930 "+b+" \u092e\u0947\u0902 \u0938\u0947 "+a+"% \u0918\u091f\u0928\u0947 \u092a\u0930 "+c+" \u092c\u091a\u093e\u0964 \u092f\u093e\u0928\u0940 "+d+"% \u0915\u092e\u0964"},
aoH(a,b){return"\u092e\u0948\u0902\u0928\u0947 \u090f\u0915 \u0938\u0902\u0916\u094d\u092f\u093e \u0938\u094b\u091a\u0940, \u0909\u0938 \u092a\u0930 "+a+" \u0915\u093f\u092f\u093e \u0914\u0930 "+b+" \u092e\u093f\u0932\u093e\u0964 \u092e\u0947\u0930\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0915\u094d\u092f\u093e \u0925\u0940?"},
