anX(a,b){return a+" \u0939\u093f\u0938\u094d\u0938\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0939\u093f\u0938\u094d\u0938\u094b\u0902 \u0938\u0947 \u090f\u0915 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0916\u0902\u092d\u093e \u091a\u093e\u0939\u093f\u090f: "+b+"\u0964"},
anY(a){return a+" \u0926\u094b\u0938\u094d\u0924 \u092e\u093f\u0932\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0939\u0930 \u0915\u094b\u0908 \u092c\u093e\u0915\u0940 \u0938\u092d\u0940 \u0938\u0947 \u090f\u0915-\u090f\u0915 \u092c\u093e\u0930 \u0939\u093e\u0925 \u092e\u093f\u0932\u093e\u0924\u093e \u0939\u0948\u0964 \u0915\u0941\u0932 \u0915\u093f\u0924\u0928\u0940 \u092c\u093e\u0930 \u0939\u093e\u0925 \u092e\u093f\u0932\u093e\u090f \u0917\u090f?"},
anZ(a,b,c,d){return a+" \u092e\u0947\u0902 \u0938\u0947 \u0939\u0930 \u0915\u094b\u0908 "+b+" \u0932\u094b\u0917\u094b\u0902 \u0938\u0947 \u0939\u093e\u0925 \u092e\u093f\u0932\u093e\u0924\u093e \u0939\u0948: "+a+" \xd7 "+b+" = "+c+"\u0964 \u0907\u0938\u092e\u0947\u0902 \u0939\u0930 \u092c\u093e\u0930 \u0939\u093e\u0925 \u092e\u093f\u0932\u093e\u0928\u093e \u0926\u094b \u092c\u093e\u0930 \u0917\u093f\u0928\u093e \u0917\u092f\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u091c\u0935\u093e\u092c "+d+" \u0939\u0948\u0964"},
gaoc(){return"\u0907\u0938 \u0926\u094d\u0935\u0940\u092a \u092a\u0930 \u201c\u0938\u091a\u094d\u091a\u0947\u201d \u0939\u092e\u0947\u0936\u093e \u0938\u091a \u092c\u094b\u0932\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u201c\u091d\u0942\u0920\u0947\u201d \u0939\u092e\u0947\u0936\u093e \u091d\u0942\u0920 \u092c\u094b\u0932\u0924\u0947 \u0939\u0948\u0902\u0964"},
ao7(a,b){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c"+b+" \u091d\u0942\u0920\u093e \u0939\u0948\u0964\u201d"},
ao8(a,b){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c"+b+" \u0938\u091a\u094d\u091a\u093e \u0939\u0948\u0964\u201d"},
aoa(a){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c\u0939\u092e \u0926\u094b\u0928\u094b\u0902 \u090f\u0915 \u0939\u0940 \u0924\u0930\u0939 \u0915\u0947 \u0939\u0948\u0902\u0964\u201d"},
ao6(a){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c\u0939\u092e \u0926\u094b\u0928\u094b\u0902 \u0905\u0932\u0917-\u0905\u0932\u0917 \u0924\u0930\u0939 \u0915\u0947 \u0939\u0948\u0902\u0964\u201d"},
ao9(a){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c\u0939\u092e \u092e\u0947\u0902 \u0938\u0947 \u0915\u092e \u0938\u0947 \u0915\u092e \u090f\u0915 \u091d\u0942\u0920\u093e \u0939\u0948\u0964\u201d"},
ao5(a){return a+" \u0915\u0939\u0924\u093e \u0939\u0948: \u201c\u0939\u092e \u0926\u094b\u0928\u094b\u0902 \u091d\u0942\u0920\u0947 \u0939\u0948\u0902\u0964\u201d"},
gaob(){return"\u0915\u094c\u0928 \u0938\u091a\u094d\u091a\u093e \u0939\u0948?"},
ao0(a,b){return a+" \u0914\u0930 "+b+" \u0926\u094b\u0928\u094b\u0902"},
